mapper.select:
SELECT * FROM itinerary_node
WHERE day_id = #{dayId}
ORDER BY seq ASC

mapper.update:
UPDATE itinerary_node
SET day_id = #{dayId}, place_id = #{placeId}, place_name = #{placeName},
    node_type = #{nodeType}, seq = #{seq}, start_time = #{startTime},
    end_time = #{endTime}, cost = #{cost}, is_abnormal = #{isAbnormal}
WHERE id = #{id}
